<?php
/** Slice 3 proof — sharing (spec "Proof" 1–4, 6–7, 10–11): additive shares, a department's and a group's reach, a guest by name, an application row, a document's own rows, explain, level set and remove, my shares, a view holder's share screen. */
require __DIR__ . '/lib.php';
$seed = seed_store();
seed_people();
$contracts = $seed['contracts'];
$acme = $seed['board_doc'];
$board = $seed['board_root'];
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
pdo()->prepare("INSERT INTO folders (library_id, parent_id, name, owner_member_id, created_by) VALUES ((SELECT library_id FROM folders WHERE id = :c), :c, 'Minutes', 27, 27) ON CONFLICT DO NOTHING")->execute(['c' => $board]);
$minutes = (int) one("SELECT id FROM folders WHERE parent_id = :b AND name = 'Minutes'", ['b' => $board]);
$minDoc = (int) one('SELECT document_id FROM dc_version_add(NULL, :f, :n, (SELECT blob_id FROM dc_blob_claim(:s, 700)), :n, :m, 700, :s, 27)', ['f' => $minutes, 'n' => 'minutes-jan.docx', 'm' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 's' => hash('sha256', 's3:minutes')]);

echo "1. A share to a person is additive\n";
$r = page(actor(28), '/f/' . $contracts);
ok($r['code'] === 404 && page(actor(28), '/documents/' . $acme)['code'] === 404, 'Bea (outside the group) cannot see Contracts nor acme');
$r = post_j(27, '/access/share.php', ['folder' => $contracts, 'member' => 28, 'level' => 'view']);
$aid = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && $aid > 0 && str_contains($r['json']['did'] ?? '', 'Shared Contracts with SMOKE Bea at view') && str_ends_with($r['json']['location'] ?? '', '/folders/' . $contracts . '/share?notice=shared'), 'share_member: ok, did, the row\'s id, lands on the share screen');
$rows = access_of('folder', $contracts);
$kinds = array_map(static fn (array $x): string => $x['principal_kind'] . ':' . $x['level'], $rows); sort($kinds);
ok(count($rows) === 2 && $kinds === ['group:edit', 'member:view'], 'the first explicit row carried the group\'s base along (additive sharing)');
ok(page(actor(28), '/f/' . $contracts)['code'] === 200 && page(actor(28), '/documents/' . $acme)['code'] === 200 && page(actor(28), '/f/' . $minutes)['code'] === 404, 'Bea sees Contracts and acme, not Minutes');
ok(page(actor(31), '/f/' . $contracts)['code'] === 404, 'Lee (outside, not named) still cannot');
ok(page(actor(26), '/documents/' . $acme)['code'] === 200 && level_of(26, 'document', $acme) === 'edit', 'the group still edits (the row raised Bea, lowered nobody)');
$ev = last_event('access.share');
ok($ev !== null && (int) $ev['folder_id'] === $contracts && json_decode($ev['after'], true)['principal_id'] === 28 && (int) $ev['entity_id'] === $aid, 'logged access.share with the folder and the row');
$b = bell(28, 'share_received');
ok(count($b) === 1 && str_contains($b[0]['title'], 'shared Contracts with you') && (int) one("SELECT count(*) FROM notification_outbox WHERE member_id = 28 AND kind = 'share_received'") === 1, 'Bea\'s bell rang once and one email was queued');
$r = post_j(27, '/access/share.php', ['folder' => $contracts, 'member' => 28, 'level' => 'view']);
ok($r['code'] === 200 && count(bell(28, 'share_received')) === 1, 'sharing the same again rings nothing twice (dedupe)');
$r = page(actor(28), '/shared/');
ok($r['code'] === 200 && str_contains($r['body'], 'id="shared-row-folder-' . $contracts . '"') && str_contains($r['body'], 'SMOKE Marco'), 'Bea\'s Shared with me lists Contracts, shared by Marco');
$j = get_json(28, '/shared/')['json']['data'] ?? [];
ok(($j['rows'][0]['kind'] ?? '') === 'folder' && ($j['rows'][0]['id'] ?? 0) === $contracts && ($j['rows'][0]['level'] ?? '') === 'view', 'the JSON row: kind, id, level');

echo "2. A department, a group, an agent\n";
$r = post_j(27, '/access/share-department.php', ['folder' => $contracts, 'department' => 8, 'level' => 'edit']);
ok($r['code'] === 200 && page(actor(30), '/f/' . $contracts)['code'] === 200 && level_of(31, 'folder', $contracts) === 'edit', 'share_department: Dana and Lee (Engineering) edit Contracts');
ok(count(bell(30, 'share_received')) === 1 && count(bell(31, 'share_received')) === 1, '...each told once');
ok(level_of(29, 'folder', $contracts) === 'none', 'a guest is never reached by a department row');
$r = post_j(27, '/access/share-agent.php', ['folder' => $contracts, 'agent' => 42, 'level' => 'view']);
ok($r['code'] === 200 && level_of(42, 'folder', $contracts) === 'view', 'share_agent: the Clerk (42) views Contracts');
$r = post_j(27, '/access/share-agent.php', ['folder' => $contracts, 'agent' => 28, 'level' => 'view']);
ok($r['code'] === 422 && str_contains($r['body'], 'not an agent'), 'share_agent with a person: 422');
$r = post_j(27, '/access/share-group.php', ['folder' => $minutes, 'group' => $seed['group'], 'level' => 'view']);
ok($r['code'] === 200 && count(access_of('folder', $minutes)) === 1, 'share_group with the library\'s own group on Minutes: one row (the base principal is the row)');
$r = post_j(27, '/access/share.php', ['folder' => $contracts, 'member' => 28, 'level' => 'upload', 'kind' => 'folder']);
ok($r['code'] === 200 && level_of(28, 'folder', $contracts) === 'upload', 'the same person again at upload: the level is set, not a second row');
$r = post_j(27, '/access/share.php', ['document' => $acme, 'member' => 31, 'level' => 'upload']);
ok($r['code'] === 422 && ($r['json']['error']['fields']['level'] ?? '') !== '', 'upload on a document: 422 on the field');

echo "3. A guest by name — a person does it, an agent pauses\n";
$r = post_j(27, '/access/share.php', ['folder' => $minutes, 'member' => 29, 'level' => 'view']);
ok($r['code'] === 200 && last_event('access.share_guest') !== null && (int) last_event('access.share_guest')['folder_id'] === $minutes, 'a person\'s share to a guest through the person form is routed to share_guest and logged so');
ok(page(actor(29), '/f/' . $minutes)['code'] === 200 && page(actor(29), '/documents/' . $minDoc)['code'] === 200 && page(actor(29), '/f/' . $contracts)['code'] === 404, 'Ann sees Minutes and its document, nothing else');
$r = page(actor(29), '/shared/');
ok($r['code'] === 200 && str_contains($r['body'], 'id="shared-row-folder-' . $minutes . '"') && str_contains($r['body'], 'id="shared-row-document-' . $seed['guest_doc'] . '"'), 'Ann\'s Shared with me lists Minutes and the file Marco shared with her');
$r = post_j(27, '/access/share-guest.php', ['folder' => $minutes, 'guest' => 28, 'level' => 'view']);
ok($r['code'] === 422 && str_contains($r['body'], 'not a guest'), 'share_guest with an insider: 422');
$seamusRoot = (int) one("INSERT INTO folders (library_id, parent_id, name, owner_member_id, created_by) VALUES ((SELECT library_id FROM folders WHERE id = $board), $board, 'Seamus notes', 40, 40) RETURNING id");
$r = post_agent(40, 913, '/access/share.php', ['folder' => $seamusRoot, 'member' => 29, 'level' => 'view']);
ok($r['code'] === 422 && str_contains($r['body'], 'share_guest'), 'an agent sharing with a guest through share_member is told to use share_guest (the paused action)');
$r = post_agent(40, 913, '/access/share-guest.php', ['folder' => $seamusRoot, 'guest' => 29, 'level' => 'view']);
ok($r['code'] === 200 && last_event('access.share_guest')['source'] === 'agent', 'share_guest by an agent on its own folder: done here — the kernel\'s hook is what pauses it (the registry says external_send)');
$r = post_agent(40, 913, '/access/share.php', ['folder' => $contracts, 'member' => 31, 'level' => 'view']);
ok($r['code'] === 403, 'an agent at edit (not manage) on Contracts cannot share it: 403');

echo "4. An application\n";
$r = post_j(27, '/access/share-application.php', ['folder' => $contracts, 'application' => 'knowledge']);
ok($r['code'] === 200 && (bool) one("SELECT dc_application_can_see_document(:d, 'knowledge')", ['d' => $acme]) && !(bool) one("SELECT dc_application_can_see_document(:d, 'helpdesk')", ['d' => $acme]), 'share_application knowledge: dc_application_can_see_document answers for knowledge, not helpdesk');
ok(last_event('access.share_application') !== null && json_decode(last_event('access.share_application')['after'], true)['principal_ref'] === 'knowledge', 'logged access.share_application with the key');
$r = post_j(27, '/access/share-application.php', ['document' => $acme, 'application' => 'knowledge']);
ok($r['code'] === 422 || $r['code'] === 404, 'an application share names a folder, never one document (' . $r['code'] . ')');
$r = post_j(27, '/access/share-application.php', ['folder' => $contracts, 'application' => 'Bad Key!']);
ok($r['code'] === 422, 'a bad catalog key: 422');

echo "5. A document's own rows\n";
$r = post_j(27, '/access/share.php', ['document' => $acme, 'member' => 31, 'level' => 'view']);
ok($r['code'] === 200 && (bool) one('SELECT own_access FROM documents WHERE id = :d', ['d' => $acme]), 'a share on the document alone: own_access set');
ok(page(actor(31), '/documents/' . $acme)['code'] === 200, 'Lee sees acme by its own row');
ok(level_of(28, 'document', $acme) === 'none' && page(actor(28), '/documents/' . $acme)['code'] === 404, 'Bea (upload on the folder) no longer sees it: the file follows its own rows now');
ok(level_of(27, 'document', $acme) === 'manage' && level_of(1, 'document', $acme) === 'manage', 'the owner and the admin still manage it');
$r = page(actor(27), '/documents/' . $acme . '/share');
ok($r['code'] === 200 && str_contains($r['body'], 'id="share-own-access"') && str_contains($r['body'], 'id="share-row-' . access_id('document', $acme, 'member', 31) . '"'), 'the document\'s share screen says it no longer follows the folder and lists its row');
$r = page(actor(27), '/documents/' . $acme);
ok($r['code'] === 200 && preg_match('/id="document-access-line">([^<]+)</', $r['body'], $m) && str_contains($m[1], 'this file only') && str_contains($r['body'], 'id="document-share-btn"') && str_contains($r['body'], 'href="/documents/' . $acme . '/share"'), 'the document page\'s access line says "this file only" and the Share button links to the share screen');
$lid = access_id('document', $acme, 'member', 31);
$r = post_j(27, '/access/remove.php', ['access' => $lid, 'kind' => 'document']);
ok($r['code'] === 200 && !(bool) one('SELECT own_access FROM documents WHERE id = :d', ['d' => $acme]) && level_of(28, 'document', $acme) === 'none' && level_of(26, 'document', $acme) === 'edit', 'removing the last own row: the file follows its folder again (Priya edits; Bea at upload sees only her own)');

echo "6. Explain, level set, remove, the share screen\n";
$r = get_json(27, '/access/explain?folder=' . $contracts . '&member=28');
$reasons = array_column($r['json']['data']['reasons'] ?? [], 'reason');
ok($r['code'] === 200 && $reasons === ['folder'] && str_contains(json_encode($r['json']), 'SMOKE Bea'), 'explain Bea on Contracts: a row on this folder');
$r = get_json(27, '/access/explain?document=' . $acme . '&member=27');
ok(in_array('owner', array_column($r['json']['data']['reasons'] ?? [], 'reason'), true), 'explain Marco on acme: he owns it');
$r = get_json(27, '/access/explain?document=' . $minDoc . '&member=29');
ok(array_intersect(['folder', 'inherited'], array_column($r['json']['data']['reasons'] ?? [], 'reason')) !== [], 'explain Ann on the minutes document: the row on Minutes');
$r = get_json(28, '/access/explain?folder=' . $contracts . '&member=27');
ok($r['code'] === 403, 'a non-manager asking about someone else: 403');
$r = get_json(28, '/access/explain?folder=' . $contracts);
ok($r['code'] === 200 && ($r['json']['data']['member'] ?? 0) === 28, '...but may ask about themselves');
$r = page(actor(28), '/folders/' . $contracts . '/share');
ok($r['code'] === 200 && str_contains($r['body'], 'id="share-not-manager"') && !str_contains($r['body'], 'id="share-table"'), 'a view/upload holder opening the share screen sees only their own explanation, no rows');
$r = page(actor(27), '/folders/' . $contracts . '/share');
ok($r['code'] === 200 && str_contains($r['body'], 'id="share-table"') && str_contains($r['body'], 'id="share-add-person"') && str_contains($r['body'], 'id="share-restrict-btn"') && str_contains($r['body'], 'id="share-base-line"') && str_contains($r['body'], 'Everyone in the group SMOKE Board edits'), 'the manager\'s share screen: the base line, the table, the add forms, Restrict');
$r = page(actor(27), '/folders/' . $contracts . '/share?member=28');
ok($r['code'] === 200 && str_contains($r['body'], 'id="explain-result"') && str_contains($r['body'], 'SMOKE Bea can see this because'), '"check a person" explains on the screen');
$j = get_json(27, '/folders/' . $contracts . '/share')['json']['data'] ?? [];
ok(isset($j['access']['explicit'], $j['access']['base_line'], $j['mine'], $j['links']) && count($j['access']['explicit']) === 5 && !isset($j['access']['explicit'][0]['token_hash']), 'the share screen\'s JSON: the base line, five explicit rows, my reasons, the links summary');
$bea = access_id('folder', $contracts, 'member', 28);
$r = post_j(27, '/access/level.php', ['access' => $bea, 'level' => 'edit', 'kind' => 'folder']);
ok($r['code'] === 200 && level_of(28, 'folder', $contracts) === 'edit' && last_event('access.level_set') !== null && json_decode(last_event('access.level_set')['before'], true)['level'] === 'upload', 'share_level_set: Bea to edit; logged with before and after');
$r = post_j(27, '/access/level.php', ['access' => $bea, 'level' => 'none', 'kind' => 'folder']);
ok($r['code'] === 200 && level_of(28, 'folder', $contracts) === 'none', '...to none: the row stays, the reach goes');
$r = post_j(26, '/access/level.php', ['access' => $bea, 'level' => 'view', 'kind' => 'folder']);
ok($r['code'] === 403, 'an editor of the folder (not a manager) cannot set a level: 403');
$r = post_j(27, '/access/remove.php', ['access' => $bea, 'kind' => 'folder']);
ok($r['code'] === 200 && access_id('folder', $contracts, 'member', 28) === 0 && last_event('access.unshare') !== null, 'share_remove: the row is gone; logged access.unshare');
$r = post_j(27, '/access/remove.php', ['access' => 999999]);
ok($r['code'] === 404, 'a share that is not there: 404');
$sub = (int) one("INSERT INTO folders (library_id, parent_id, name, owner_member_id, created_by) VALUES ((SELECT library_id FROM folders WHERE id = $contracts), $contracts, 'Sub', 27, 27) RETURNING id");
ok((int) one('SELECT access_root_id FROM folders WHERE id = :s', ['s' => $sub]) === $contracts, 'a new subfolder\'s access root is Contracts (it has rows)');
foreach (access_of('folder', $minutes) as $row) { post_j(27, '/access/remove.php', ['access' => access_id('folder', $minutes, $row['principal_kind'], $row['principal_id'] === null ? null : (int) $row['principal_id']), 'kind' => 'folder']); }
ok(access_of('folder', $minutes) === [] && one('SELECT access_root_id FROM folders WHERE id = :m', ['m' => $minutes]) === null && level_of(26, 'folder', $minutes) === 'edit' && level_of(29, 'folder', $minutes) === 'none', 'removing a folder\'s last row: inheritance resumes (the group edits again; the guest is gone)');

echo "7. My shares\n";
$r = page(actor(27), '/shares/mine');
ok($r['code'] === 200 && str_contains($r['body'], 'id="my-shares-table"') && str_contains($r['body'], 'Engineering') && str_contains($r['body'], 'knowledge'), 'My shares lists what Marco granted: the department, the application' . ($r['code'] === 200 ? '' : ' (' . $r['code'] . ' ' . substr(text_of($r['body']), 0, 160) . ')'));
pdo()->exec("UPDATE document_access SET created_at = now() - interval '120 days' WHERE document_id = " . $seed['guest_doc'] . " AND principal_id = 29");
$r = page(actor(27), '/shares/mine');
ok(str_contains($r['body'], 'id="stale-document-' . $seed['guest_doc'] . '"') && str_contains($r['body'], 'older than 90 days'), 'a guest share older than 90 days is flagged stale');
$j = get_json(27, '/shares/mine')['json']['data'] ?? [];
$stale = array_values(array_filter($j['rows'] ?? [], static fn (array $x): bool => !empty($x['stale'])));
ok(count($stale) === 1 && $stale[0]['is_guest'] === true, '...and in the JSON');
ok(page(actor(28), '/shares/mine')['code'] === 200 && page(actor(29), '/shares/mine')['code'] === 403, 'a Member sees their (empty) shares; a guest holds no documents.share: 403');

echo "8. Anonymous and the registry\n";
ok(req('POST', '/access/share.php', ['form' => ['folder' => $contracts, 'member' => 28, 'level' => 'view']])['code'] === 302, 'an anonymous share goes to the launcher (302)');
ok(req('GET', '/folders/' . $contracts . '/share')['code'] === 302, 'an anonymous share screen: the launcher');
finish();
